/**
 * INCIDENT AI bot gate (also accepts legacy @fw-noc-deploy).
 * Sessions keyed by (channel, thread_ts) or DM (channel, __direct__).
 * Twin-event guard: same (channel, message ts) within 90s → drop (prevents double Slack delivery / double reply).
 * Slack trigger: **message** only — do NOT subscribe to app_mention on the Slack app.
 */
const BOT_USER_ID = '';
/** INCIDENT AI Slack member id — must match <@U…> in kickoff messages. */
const INCIDENT_AI_USER_ID = 'U0B82QCV268';

const INCIDENT_AI_LABEL_RE = /incident\s*ai/i;
const LEGACY_NOC_LABEL_RE = /fw-noc-deploy/i;
const TTL_MS = 7 * 24 * 60 * 60 * 1000;

const RESTRICT_NOC_TO_ALLOWLIST = false;
const NOC_CHANNEL_ALLOWLIST = new Set(['C012T9FG8NA', 'C0B34UWLS5V']);
/** Thread follow-ups without @ work in any channel after a kickoff (recommended). */
const THREAD_CONTINUATION_ANY_CHANNEL = true;
const THREAD_CONTINUATION_CHANNELS = new Set(['C012T9FG8NA', 'C0B34UWLS5V']);
const DM_MARK = '__direct__';

const normSlackTs = (t) => {
  if (t === undefined || t === null || t === '') return '';
  const s = String(t).trim();
  const m = /^(\d+)\.(\d+)$/.exec(s);
  if (!m) return s;
  const frac = m[2].replace(/0+$/, '') || '0';
  return `${m[1]}.${frac}`;
};

const tsFrom = (obj) => {
  if (!obj || typeof obj !== 'object') return '';
  const v = obj.thread_ts ?? obj.message?.thread_ts;
  if (v === undefined || v === null) return '';
  return String(v).trim() || '';
};

function messageText(ev) {
  if (!ev || typeof ev !== 'object') return '';
  if (typeof ev.text === 'string' && ev.text.trim()) return ev.text;
  const parts = [];
  const blocks = ev.blocks || ev.message?.blocks;
  if (Array.isArray(blocks)) {
    for (const b of blocks) {
      if (b?.text?.text) parts.push(String(b.text.text));
      if (Array.isArray(b?.elements)) {
        for (const el of b.elements) {
          if (el?.text) parts.push(String(el.text));
          if (Array.isArray(el?.elements)) {
            for (const inner of el.elements) {
              if (inner?.text) parts.push(String(inner.text));
            }
          }
        }
      }
    }
  }
  return parts.join(' ').trim();
}

function isAllowedBotKickoff(text) {
  const trimmed = String(text || '').trimStart();
  if (INCIDENT_AI_LABEL_RE.test(trimmed) || LEGACY_NOC_LABEL_RE.test(trimmed)) {
    return true;
  }
  const re = /<@([UW][A-Z0-9]{8,})(?:\|([^>]+))?>/gi;
  let m;
  while ((m = re.exec(trimmed)) !== null) {
    const uid = m[1];
    const label = (m[2] || '').trim();
    if (BOT_USER_ID && uid === BOT_USER_ID) return true;
    if (INCIDENT_AI_USER_ID && uid === INCIDENT_AI_USER_ID) return true;
    if (INCIDENT_AI_LABEL_RE.test(label) || LEGACY_NOC_LABEL_RE.test(label)) return true;
  }
  return false;
}

/** Leading <@U…> — Slack often omits |display-name; accept when bot id matches or not configured yet. */
function leadingMentionKickoff(text) {
  const trimmed = String(text || '').trimStart();
  const m = /^<@(U[A-Z0-9]{8,})(?:\|([^>]+))?>/i.exec(trimmed);
  if (!m) return false;
  const uid = m[1];
  const label = (m[2] || '').trim();
  if (INCIDENT_AI_USER_ID && uid === INCIDENT_AI_USER_ID) return true;
  if (BOT_USER_ID && uid === BOT_USER_ID) return true;
  if (INCIDENT_AI_LABEL_RE.test(label) || LEGACY_NOC_LABEL_RE.test(label)) return true;
  if (!INCIDENT_AI_USER_ID && !BOT_USER_ID) return true;
  return false;
}

const sd = $getWorkflowStaticData('global');
if (!sd.fwNocSessions) sd.fwNocSessions = {};
const sessions = sd.fwNocSessions;

const raw = $input.first().json || {};
const rawEv =
  raw && typeof raw === 'object' && raw.event && typeof raw.event === 'object'
    ? raw.event
    : null;

let e;
if (rawEv) {
  e = { ...rawEv };
  if (!e.channel_type && rawEv.channel_type) e.channel_type = rawEv.channel_type;
} else {
  e = { ...raw };
}

if (e.type === 'message' && e.subtype === 'message_changed' && e.message && typeof e.message === 'object') {
  const outerCt = e.channel_type;
  const outerTh = tsFrom(e);
  const inner = { ...e.message };
  const ch = e.channel ?? e.channel_id ?? inner.channel;
  if (typeof ch === 'string' && inner.channel === undefined) inner.channel = ch;
  if (typeof ch === 'string' && inner.channel_id === undefined) inner.channel_id = ch;
  if (outerCt && inner.channel_type === undefined) inner.channel_type = outerCt;
  const innerTh = tsFrom(inner);
  if (!innerTh && outerTh) inner.thread_ts = outerTh;
  e = inner;
}

const mergedThreadTs =
  tsFrom(e) || tsFrom(rawEv) || tsFrom(raw) || tsFrom(e.previous_message);
if (mergedThreadTs && (!e.thread_ts || String(e.thread_ts).trim() === '')) {
  e.thread_ts = mergedThreadTs;
}

const channelRaw = e.channel ?? e.channel_id ?? raw.channel ?? raw.channel_id;
const channel =
  typeof channelRaw === 'string' ? channelRaw : channelRaw?.id ?? null;

let eventType = e.type || raw.type || rawEv?.type;
if (!eventType && channel && (e.ts || raw.ts)) eventType = 'message';

if (eventType !== 'message' && eventType !== 'app_mention') {
  return [];
}

if (eventType === 'app_mention') {
  return [];
}

if (e.bot_id || e.subtype === 'bot_message') {
  return [];
}
const botIds = [BOT_USER_ID, INCIDENT_AI_USER_ID].filter(Boolean);
if (botIds.includes(e.user)) {
  return [];
}

const nonConversation = new Set([
  'message_deleted',
  'channel_join',
  'group_join',
  'channel_leave',
  'group_leave',
  'channel_topic',
  'channel_purpose',
  'channel_name',
  'channel_archive',
  'channel_unarchive',
  'pinned_item',
  'unpinned_item',
  'tombstone',
  'channel_convert_to_private',
]);

if (eventType === 'message' && e.subtype && nonConversation.has(e.subtype)) {
  return [];
}

if (!channel || !e.ts) {
  return [];
}

const isDmLike =
  e.channel_type === 'im' ||
  e.channel_type === 'mpim' ||
  (typeof channel === 'string' && /^D[A-Z0-9]{8,}$/i.test(channel));

const isChannelOrGroup =
  typeof channel === 'string' && /^[CG][A-Z0-9]{8,}$/i.test(channel);

if (!isDmLike) {
  if (!isChannelOrGroup) return [];
  if (RESTRICT_NOC_TO_ALLOWLIST && !NOC_CHANNEL_ALLOWLIST.has(channel)) {
    return [];
  }
}

const now = Date.now();
for (const k of Object.keys(sessions)) {
  if (k.startsWith('__')) continue;
  const meta = sessions[k];
  if (meta && now - (meta.at || 0) > TTL_MS) delete sessions[k];
}

const skNorm = (ch, root) => `${ch}:${normSlackTs(root)}`;
const skRaw = (ch, root) => `${ch}:${String(root).trim()}`;

function sessionHas(ch, normRoot, rawRoot, map) {
  if (!normRoot) return false;
  if (map[skNorm(ch, normRoot)]) return true;
  if (rawRoot && map[skRaw(ch, rawRoot)]) return true;
  if (rawRoot && map[skNorm(ch, rawRoot)]) return true;
  return false;
}

function sessionTouch(ch, normRoot, rawRoot, map, t) {
  const k1 = skNorm(ch, normRoot);
  map[k1] = { at: t };
  if (rawRoot && skRaw(ch, rawRoot) !== k1) map[skRaw(ch, rawRoot)] = { at: t };
}

function sessionBump(ch, normRoot, rawRoot, map, t) {
  const ks = [skNorm(ch, normRoot)];
  if (rawRoot) {
    const r = skRaw(ch, rawRoot);
    const n2 = skNorm(ch, rawRoot);
    if (!ks.includes(r)) ks.push(r);
    if (!ks.includes(n2)) ks.push(n2);
  }
  for (const k of ks) {
    if (map[k]) map[k] = { at: t };
  }
}

const text = messageText(e) || messageText(raw) || '';
const ts = normSlackTs(e.ts);
const rawThreadTs = e.thread_ts ? String(e.thread_ts).trim() : '';
const threadTs = rawThreadTs ? normSlackTs(rawThreadTs) : '';

const outerSubtype = rawEv?.subtype || raw?.subtype || '';
const skipTwinDedupe =
  outerSubtype === 'message_changed' || e.subtype === 'message_changed';
if (!sd.__fwTwinMsgDedupe) sd.__fwTwinMsgDedupe = {};
const msgDedupeKey = `${channel}:${normSlackTs(e.ts)}`;
if (!skipTwinDedupe) {
  const prevSeen = sd.__fwTwinMsgDedupe[msgDedupeKey];
  if (prevSeen && now - prevSeen < 90000) {
    return [];
  }
  sd.__fwTwinMsgDedupe[msgDedupeKey] = now;
  for (const k of Object.keys(sd.__fwTwinMsgDedupe)) {
    if (now - sd.__fwTwinMsgDedupe[k] > 300000) delete sd.__fwTwinMsgDedupe[k];
  }
}

const trimmed = text.trimStart();
const kickoffText =
  leadingMentionKickoff(trimmed) || isAllowedBotKickoff(trimmed);

const threadFollowupOk =
  THREAD_CONTINUATION_ANY_CHANNEL || THREAD_CONTINUATION_CHANNELS.has(channel);
const continuingThread =
  !!threadTs && threadFollowupOk && sessionHas(channel, threadTs, rawThreadTs, sessions);
const continuingDmRoot =
  isDmLike && !threadTs && sessionHas(channel, DM_MARK, DM_MARK, sessions);

const continuingForFile = continuingThread || continuingDmRoot;

if (
  eventType === 'message' &&
  e.subtype === 'file_share' &&
  !continuingForFile &&
  !kickoffText &&
  !(isDmLike && !threadTs)
) {
  return [];
}

let allowed = false;
if (isDmLike && !threadTs) {
  if (continuingDmRoot) {
    allowed = true;
    sessionBump(channel, DM_MARK, DM_MARK, sessions, now);
  } else if (kickoffText) {
    sessionTouch(channel, DM_MARK, DM_MARK, sessions, now);
    allowed = true;
  }
} else if (!threadTs) {
  if (kickoffText) {
    sessionTouch(channel, ts, e.ts, sessions, now);
    allowed = true;
  }
} else if (continuingThread) {
  allowed = true;
  sessionBump(channel, threadTs, rawThreadTs, sessions, now);
  if (ts && threadTs && ts !== threadTs) sessionBump(channel, ts, e.ts, sessions, now);
} else if (kickoffText) {
  sessionTouch(channel, threadTs, rawThreadTs, sessions, now);
  if (ts && threadTs && ts !== threadTs) sessionTouch(channel, ts, e.ts, sessions, now);
  allowed = true;
}

if (!allowed) {
  return [];
}

return [
  {
    json: {
      ...e,
      text: text || e.text,
      _gateBot: 'incident-ai',
      _gateAllowedAt: now,
      _gateKickoff: !!kickoffText,
    },
  },
];

const staticData = $getWorkflowStaticData('global');
const data = $input.first().json;
const rawResults = Array.isArray(data.results) ? data.results : [];

const incidentTime = (r) => {
  if (!r || typeof r !== 'object') return 0;
  const pick = r.updated_at || r.start_time || r.end_time || r.created_at;
  if (!pick) return 0;
  const n = Date.parse(pick);
  return Number.isFinite(n) ? n : 0;
};

const results = rawResults.slice().sort((a, b) => incidentTime(b) - incidentTime(a));

const active = results
  .filter((r) => r && (r.end_time === null || r.end_time === undefined))
  .slice(0, 25)
  .map((r) => ({
    id: r.id,
    title: r.title,
    description: r.description,
    start_time: r.start_time,
    end_time: r.end_time,
  }));

// Stable fingerprint: sorted active id + open/closed (not full JSON — avoids missing notifies on field reorder / whitespace).
const activeSig = active
  .map((r) => `${r.id}:${r.end_time === null || r.end_time === undefined ? 'open' : 'closed'}`)
  .sort()
  .join('|');
const newestId = results[0]?.id ?? null;
const fingerprint = `${activeSig}||newest:${newestId}`;

const prev = staticData.freshstatusFingerprint;
if (prev === undefined) {
  staticData.freshstatusFingerprint = fingerprint;
  return [];
}

if (prev === fingerprint) {
  return [];
}

staticData.freshstatusFingerprint = fingerprint;

const systemInstructions = "You are an internal incident comms assistant for Freshworks outages.\nWrite EXACTLY 2 or 3 short lines, plain text, no markdown, no bullets.\nLine 1: Impacted product(s) and region(s) if known; if unknown say product/region unclear.\nLine 2: Customer-visible symptom in one sentence.\nLine 3: Cause bucket: third-party/cloud provider vs Freshworks internal vs maintenance vs unknown — pick one with a brief reason.\nPrefix the first line with [STATUS] ";
const userBody = `Freshstatus incidents payload (trimmed). Treat incidents with end_time null as ACTIVE/ongoing.\n\nACTIVE:\n${JSON.stringify(active)}\n\nTOP_RECENT (may include resolved):\n${JSON.stringify(
        results.slice(0, 10).map((r) => ({
          id: r.id,
          title: r.title,
          start_time: r.start_time,
          end_time: r.end_time,
        })),
      )}`;

return [
  {
    json: {
      kind: 'freshstatus_change',
      llmUser: `${systemInstructions}\n\n---\n\n${userBody}`,
    },
  },
];

const staticData = $getWorkflowStaticData('global');

const rows = $input.all().map((i) => i.json).filter((m) => m && m.ts && m.type === 'message');
if (!rows.length) {
  return [];
}

const numericTs = (ts) => Number(ts);

let baseline = staticData.lastFwSlackTs ? numericTs(staticData.lastFwSlackTs) : null;
if (baseline === null) {
  const newest = Math.max(...rows.map((r) => numericTs(r.ts)));
  staticData.lastFwSlackTs = String(newest);
  return [];
}

const fresh = rows
  .filter((r) => numericTs(r.ts) > baseline)
  .sort((a, b) => numericTs(a.ts) - numericTs(b.ts));

if (!fresh.length) {
  return [];
}

const newest = Math.max(baseline, ...fresh.map((r) => numericTs(r.ts)));
staticData.lastFwSlackTs = String(newest);

const bundle = fresh
  .map((m) => ({ ts: m.ts, user: m.user, text: m.text, subtype: m.subtype }))
  .slice(-15);

const systemInstructions = "You are an internal incident comms assistant.\nWrite EXACTLY 2 or 3 short lines, plain text, no markdown, no bullets.\nLine 1: What changed / what it means.\nLine 2: Impacted product(s) and region(s) if inferable.\nLine 3: Likely cause bucket: third-party vs internal vs unknown \u2014 brief.\nPrefix the first line with [FW-OUTAGE] ";
const userBody = `New message(s) detected in fw-outage channel (since last poll).\n\nMESSAGES_JSON:\n${JSON.stringify(bundle)}`;

return [
  {
    json: {
      kind: 'fw_outage_slack',
      llmUser: `${systemInstructions}\n\n---\n\n${userBody}`,
    },
  },
];

const meta = $('Code: Merge Freshstatus + mention').first().json;
const dbRowsRaw = $input
  .all()
  .map((i) => i.json)
  .filter((r) => r && typeof r === 'object' && !r.error);

/** n8n Select on MIM_Ticket_id has no _mysql_source column — infer from row shape. */
function inferMysqlSource(r) {
  if (r._mysql_source) return r._mysql_source;
  if (r.Ticket_field != null && (r.Slack_thread != null || r.User_id != null)) {
    return 'MIM_Ticket_id';
  }
  if (r.Slack_update_threads != null || r.Inc_update_no != null) {
    return 'All_update_threads';
  }
  if (
    r.incident_no != null ||
    r.Incident_no != null ||
    r.create_epoch_date_time != null ||
    r.FR_incident_link != null
  ) {
    return 'Outages_data';
  }
  if (r.ticket_id != null && (r.ticket_display_id != null || r.subject != null)) {
    return 'MIM_Analytics_export';
  }
  return null;
}

const dbRows = dbRowsRaw.map((r) => {
  const src = inferMysqlSource(r);
  return src && !r._mysql_source ? { ...r, _mysql_source: src } : r;
});

const epochSortKey = (r) => {
  const v = r.create_epoch_date_time ?? r.Create_epoch_date_time;
  if (v === null || v === undefined || v === '') return 0;
  const n = Number(v);
  if (Number.isFinite(n) && n > 1e8 && n < 1e14) {
    return n > 1e12 ? n / 1000 : n;
  }
  const d = Date.parse(String(v));
  return Number.isFinite(d) ? d / 1000 : 0;
};

const incidentNo = (r) => {
  const v = r.incident_no ?? r.Incident_no;
  const n = Number(v);
  return Number.isFinite(n) ? n : 0;
};

const isOutages = (r) => r._mysql_source === 'Outages_data';
const outages = dbRows.filter(isOutages).sort((a, b) => {
  const t = epochSortKey(b) - epochSortKey(a);
  if (t !== 0) return t;
  return incidentNo(b) - incidentNo(a);
});
const other = dbRows.filter((r) => !isOutages(r));
const orderedDb = [...outages, ...other];

const mimFromDb = dbRows.filter((r) => r._mysql_source === 'MIM_Ticket_id');
const analyticsFromDb = dbRows.filter((r) => r._mysql_source === 'MIM_Analytics_export');

return [
  {
    json: {
      ...meta,
      dbFwRows: orderedDb,
      dbFwRowCount: orderedDb.length,
      mimTicketDbRowCountFromDb: mimFromDb.length,
      analyticsExportRowCount: analyticsFromDb.length,
      analyticsExportRows: analyticsFromDb,
    },
  },
];

const tsFrom = (obj) => {
  if (!obj || typeof obj !== 'object') return '';
  const v = obj.thread_ts ?? obj.message?.thread_ts;
  if (v === undefined || v === null) return '';
  const s = String(v).trim();
  return s || '';
};

const e = $input.first().json || {};
let flat = e;
if (e && typeof e === 'object' && e.event && typeof e.event === 'object') {
  flat = { ...e, ...e.event };
}

const mergedTs =
  tsFrom(flat) || tsFrom(e.event) || tsFrom(e) || tsFrom(flat.previous_message);
if (mergedTs && (!flat.thread_ts || String(flat.thread_ts).trim() === '')) {
  flat.thread_ts = mergedTs;
}

const channelRaw = flat.channel ?? flat.channel_id ?? flat.item?.channel;
const replyChannel =
  typeof channelRaw === 'string' ? channelRaw : channelRaw?.id ?? channelRaw;

const mentionTs = flat.ts ?? flat.event_ts ?? flat.message?.ts;
const replyThreadTs = flat.thread_ts ?? flat.ts ?? flat.event_ts;

const rawText = typeof flat.text === 'string' ? flat.text : '';
const userText = rawText.replace(/<@[^>]+>\s*/g, '').trim();

return [
  {
    json: {
      userText:
        userText ||
        '(The user only mentioned the bot with no extra text — greet them briefly and offer help.)',
      userTextRaw: rawText,
      replyChannel,
      replyThreadTs,
      mentionTs,
      sessionId: `slack:${replyChannel}:${mentionTs}`,
      slackUserId: flat.user ?? null,
    },
  },
];

const parse = $('Code: Parse mention').first().json;

const rows = $input
  .all()
  .map((i) => i.json)
  .filter((m) => m && m.ts && m.type === 'message');

const threadBundle = rows
  .slice()
  .sort((a, b) => Number(a.ts) - Number(b.ts))
  .map((m) => ({
    ts: m.ts,
    user: m.user,
    text: typeof m.text === 'string' ? m.text : '',
    subtype: m.subtype ?? null,
  }));

return [
  {
    json: {
      ...parse,
      mentionThreadMessageCount: threadBundle.length,
      mentionThreadMessages: threadBundle,
    },
  },
];

const meta = $('Code: Enrich mention with thread').first().json;
const fs = $input.first().json || {};
const rawResults = Array.isArray(fs.results) ? fs.results : [];
const incidentTime = (r) => {
  if (!r || typeof r !== 'object') return 0;
  const pick = r.updated_at || r.start_time || r.end_time || r.created_at;
  if (!pick) return 0;
  const n = Date.parse(pick);
  return Number.isFinite(n) ? n : 0;
};
const results = rawResults.slice().sort((a, b) => incidentTime(b) - incidentTime(a));

const active = results
  .filter((r) => r && (r.end_time === null || r.end_time === undefined))
  .slice(0, 20)
  .map((r) => ({
    id: r.id,
    title: r.title,
    description: r.description,
    start_time: r.start_time,
    end_time: r.end_time,
  }));

const recent = results.slice(0, 24).map((r) => ({
  id: r.id,
  title: r.title,
  start_time: r.start_time,
  end_time: r.end_time,
}));

return [
  {
    json: {
      ...meta,
      freshstatusActive: active,
      freshstatusRecent: recent,
      freshstatusTotal: results.length,
    },
  },
];

const meta = $('Code: Merge Freshservice + context').first().json;

const slackMsgRows = Array.isArray(meta.fwSlackSnapshot)
  ? meta.fwSlackSnapshot
  : $input
      .all()
      .map((i) => i.json)
      .filter((m) => m && m.ts && m.type === 'message');
const rows = slackMsgRows.slice().sort((a, b) => Number(b.ts) - Number(a.ts));

const fwBundle = rows
  .slice(0, 35)
  .map((m) => {
    const raw = typeof m.text === 'string' ? m.text : '';
    const text = raw.length > 900 ? raw.slice(0, 900) + '…(truncated)' : raw;
    return { ts: m.ts, user: m.user, text, subtype: m.subtype ?? null };
  });

const dbRowsRaw = Array.isArray(meta.dbFwRows) ? meta.dbFwRows : [];

const truncStr = (v, n) => {
  if (v == null) return v;
  const s = String(v);
  return s.length <= n ? s : s.slice(0, n) + '…(truncated)';
};

const slimField = (key, val) => {
  if (val == null || val === '') return undefined;
  const lk = String(key).toLowerCase();
  if (/(url|link)$/.test(lk) || lk.includes('http') || lk.includes('zoom')) return val;
  if (typeof val === 'string') {
    if (/(description|resolution|impact|problem|customer)/.test(lk)) return truncStr(val, 900);
    if (
      /(start|end|created|updated|resolved|closed|timestamp|epoch|time|duration|window)/.test(
        lk,
      )
    ) {
      return truncStr(val, 800);
    }
    return truncStr(val, 650);
  }
  return val;
};

const slimRow = (r) => {
  if (!r || typeof r !== 'object') return r;
  const o = {};
  for (const [k, v] of Object.entries(r)) {
    const sv = slimField(k, v);
    if (sv !== undefined) o[k] = sv;
  }
  return o;
};

let nOut = 0;
let nTh = 0;
let nMim = 0;
const dbRowsSlim = [];
for (const r of dbRowsRaw) {
  const src = r && r._mysql_source;
  if (src === 'Outages_data') {
    if (nOut >= 18) continue;
    nOut += 1;
  } else if (src === 'All_update_threads') {
    if (nTh >= 12) continue;
    nTh += 1;
  } else if (src === 'MIM_Ticket_id') {
    if (nMim >= 12) continue;
    nMim += 1;
  }
  dbRowsSlim.push(slimRow(r));
}

const dbBlock = dbRowsSlim.length
  ? JSON.stringify(dbRowsSlim)
  : '(no database rows — check both MySQL nodes, Merge: Incident DB snapshots, credentials, or table/column names such as Outages_data / All_update_threads)';

const threadMessages = Array.isArray(meta.mentionThreadMessages) ? meta.mentionThreadMessages : [];
const threadBlock = threadMessages.length
  ? JSON.stringify(
      threadMessages.map((m) => ({
        ...m,
        text:
          typeof m.text === 'string' && m.text.length > 1200
