function tokenSet(s) {
  return new Set(
    String(s)
      .toLowerCase()
      .split(/[^a-z0-9]+/)
      .filter((w) => w.length > 3),
  );
}

function jaccard(a, b) {
  const A = tokenSet(a);
  const B = tokenSet(b);
  if (!A.size || !B.size) return 0;
  let inter = 0;
  for (const x of A) {
    if (B.has(x)) inter += 1;
  }
  return inter / Math.min(A.size, B.size);
}

function urlsOf(s) {
  const m = String(s).match(/https?:\/\/[^\s>]+/gi);
  return m ? [...new Set(m.map((u) => u.replace(/[),.;]+$/, '')))].sort().join('|') : '';
}

function normalizeDupBreaks(text) {
  let s = String(text || '').replace(/\r\n/g, '\n').trim();
  if (!s) return s;
  s = s.replace(/([.!?])\s*\n(?=[A-Z])/g, '$1\n\n');
  s = s.replace(/([^\n])\n(The |This |For the |It |Incident\b)/g, '$1\n\n$2');
  return s;
}

function collapseDupParagraphs(text) {
  const t = normalizeDupBreaks(text).trim();
  if (!t) return t;
  const parts = t.split(/\n\n+/).map((p) => p.trim()).filter(Boolean);
  if (parts.length < 2) return String(text || '').trim();
  const out = [parts[0]];
  for (let i = 1; i < parts.length; i += 1) {
    const p = parts[i];
    const prev = out[out.length - 1];
    const u1 = urlsOf(prev);
    const u2 = urlsOf(p);
    const jac = jaccard(prev, p);
    if (u1 && u2 && u1 === u2 && jac >= 0.28) continue;
    if (jac >= 0.48) continue;
    const pre = prev.slice(0, 120).toLowerCase().replace(/\s+/g, ' ');
    const cur = p.slice(0, 120).toLowerCase().replace(/\s+/g, ' ');
    if (pre === cur) continue;
    if (pre.length > 40 && cur.length > 40 && pre.slice(0, 40) === cur.slice(0, 40)) continue;
    out.push(p);
  }
  return out.join('\n\n');
}

