      'push to prod',
      'production deploy',
      'config deploy',
    ],
    textPatterns: [
      /\bdeploy(?:ment|ments|ed|ing)?\b/i,
      /\brollback\b/i,
      /\broll[\s-]?out\b/i,
      /\brelease\b/i,
      /\bcode\s+change\b/i,
      /\bconfig(?:uration)?\s+change\b/i,
      /\bpushed?\s+to\s+prod/i,
    ],
  },
  {
    key: 'third_party',
    label: 'Third-party / vendor',
    queryPhrases: [
      'third party',
      'third-party',
      'vendor',
      'external provider',
      'cloud provider',
    ],
    textPatterns: [
      /\bthird[\s-]?party\b/i,
      /\bvendor\b/i,
      /\bexternal\s+provider\b/i,
      /\b(aws|azure|gcp|google cloud|cloudflare|akamai|fastly)\b/i,
    ],
  },
  {
    key: 'infrastructure',
    label: 'Infrastructure / hardware',
    queryPhrases: [
      'infrastructure',
      'infra',
      'hardware',
      'network',
      'database',
      'db issue',
