      /\bnetwork\b/i,
      /\bdatabase\b/i,
      /\bcapacity\b/i,
      /\bserver\s+down\b/i,
      /\bhost\s+failure\b/i,
    ],
  },
  {
    key: 'configuration',
    label: 'Configuration / misconfiguration',
    queryPhrases: ['misconfiguration', 'config error', 'configuration', 'human error'],
    textPatterns: [
      /\bmisconfig/i,
      /\bconfig(?:uration)?\s+error\b/i,
      /\bhuman\s+error\b/i,
      /\bwrong\s+config\b/i,
    ],
  },
  {
    key: 'security',
