    queryPhrases: ['security', 'ddos', 'attack', 'breach'],
    textPatterns: [/\bsecurity\b/i, /\bddos\b/i, /\battack\b/i, /\bbreach\b/i],
  },
  {
    key: 'maintenance',
    label: 'Maintenance / planned',
