/**
 * Pick DB source based on what the export actually contains.
 * Historical / dashboard / cause queries → Outages_data.
 * Live MIM ticket status (open/closed/P0) without a period → analytics export.
 */
function pickQueryDataSource(base) {
  const widget = base.dashboardWidget || null;
  const segment = base.incidentReportSegmentFilter || null;
  const range = base.incidentReportRange || null;
  const analyticsCount =
    base.analyticsExportRowCount ||
    (typeof loadAnalyticsRows === 'function' ? loadAnalyticsRows(base).length : 0);

  if (segment) {
    return {
      source: 'outages',
      reason:
        'Cause queries need Outages_data (root_cause, description). Export CSV has no cause column.',
    };
  }

  const hasPeriod =
    !!range ||
    /\b(20\d{2}|january|february|march|april|may|june|july|august|september|october|november|december|jan|feb|mar|apr|jun|jul|aug|sep|oct|nov|dec|this month|last month|q[1-4]|quarter)\b/i.test(
      String(base.userText || ''),
    );

  const outagesWidgets = [
    'product_split',
    'issue_category',
    'third_party_split',
    'status_page',
    'presented_in_mom',
    'monthly_trend',
    'dashboard_overview',
    'kpi_mim_by_noc',
  ];
  if (widget && outagesWidgets.includes(widget)) {
    return {
      source: 'outages',
      reason: `${widget} needs fields not in export CSV — using Outages_data.`,
    };
  }

  if (hasPeriod) {
    return {
      source: 'outages',
      reason: 'Period reports (2026, April, etc.) use Outages_data incident history.',
    };
  }

  const liveAnalyticsWidgets = ['kpi_open_mim', 'kpi_closed_mim', 'kpi_p0'];
  if (widget && liveAnalyticsWidgets.includes(widget) && analyticsCount > 0) {
    return {
      source: 'analytics',
      reason:
        'Live MIM ticket Status/Priority from Freshservice analytics export (no period filter).',
    };
  }

  if (base.wantsIncidentReport || base.wantsCauseSegmentQuery) {
    return {
      source: 'outages',
      reason: 'Incident reports and counts use Outages_data.',
    };
  }

  return {
    source: 'outages',
    reason: 'Default: Outages_data has product, dates, and root cause.',
  };
}

function exportCapabilityHint(widgetOrSegment) {
  if (EXPORT_CAPABILITIES[widgetOrSegment] === false) {
    return (
      `Export CSV columns: ${EXPORT_CSV_COLUMNS.join(', ')}. ` +
      'Add Product / Issue Category / Root Cause to the Freshservice scheduled export to enable this from analytics.'
    );
  }
  return null;
}


/** Dashboard aggregations from MIM_Analytics_export (Major Outages 2026 style). */

const ANALYTICS_EXPORT_SOURCE = 'MIM_Analytics_export';

const DASHBOARD_WIDGET_LABELS = {
  monthly_trend: 'Monthly trend',
  kpi_mim_by_noc: 'MIM by NOC',
  kpi_p0: 'P0 Outages',
  kpi_open_mim: 'OPEN MIM',
  kpi_closed_mim: 'Closed MIMs',
  status_page: 'Status page',
  presented_in_mom: 'Presented in MOM',
  product_split: 'Product split',
  issue_category: 'Issue category',
  third_party_split: 'Third party split',
  dashboard_overview: 'Major Outages dashboard',
};

function loadAnalyticsRows(base) {
  const uniq = new Map();
  const add = (r) => {
    if (!r || typeof r !== 'object') return;
    const tid = String(r.ticket_id ?? r.Ticket_id ?? '').replace(/\D/g, '');
    const key = tid || r.ticket_display_id || `row_${uniq.size}`;
    if (!tid && !r.ticket_display_id && !r.subject) return;
    const norm = r._mysql_source ? r : { ...r, _mysql_source: ANALYTICS_EXPORT_SOURCE };
    uniq.set(key, norm);
  };
  (base.dbFwRows || []).forEach(add);
  (base.analyticsExportRows || []).forEach(add);
  try {
    ($('MySQL: MIM_Analytics_export').all() || []).forEach((item) => add(item.json));
  } catch (e) {
    /* sync branch may not have run */
  }
  try {
    const attach = $('Code: Attach DB snapshot').first().json;
    (attach.dbFwRows || []).forEach(add);
  } catch (e) {
    /* */
  }
  return [...uniq.values()];
}

function analyticsEpoch(row) {
  const v = row.created_date ?? row.Created_date;
  if (!v) return 0;
  const d = Date.parse(String(v));
  return Number.isFinite(d) ? d / 1000 : 0;
}

function analyticsRowsInRange(rows, range) {
  if (!range) return rows;
  return rows.filter((r) => {
    const ep = analyticsEpoch(r);
    return ep && ep >= range.from && ep <= range.to;
  });
}

function inferThirdPartyFromSubject(subject) {
  const s = String(subject || '').toLowerCase();
  const map = [
    ['Cloudflare', /\bcloudflare\b/i],
    ['Azure', /\bazure\b/i],
    ['AWS', /\baws\b|amazon web services/i],
    ['META', /\bmeta\b|facebook/i],
    ['Microsoft', /\bmicrosoft\b/i],
    ['Google', /\bgoogle\b|gcp\b/i],
  ];
  for (const [label, re] of map) {
    if (re.test(s)) return label;
  }
  return null;
}

function inferIssueCategoryFromRow(row) {
  if (row.issue_category) return row.issue_category;
  const s = String(row.subject || '').toLowerCase();
  if (/\bdeploy/.test(s)) return 'Deployment';
  if (/\bthird.?party\b|cloudflare|azure\b|aws\b/.test(s)) return 'Third Party';
  if (/\binfra|network|database|db\b|capacity/.test(s)) return 'Infra';
  if (/\bcode\b|bug|exception/.test(s)) return 'Code';
  if (/\bmigration\b/.test(s)) return 'Migration';
  if (/\bddos|spam|attack/.test(s)) return 'Spam/DDOS';
  return 'Other';
}

function parsedRawRow(row) {
  try {
    const raw = row.raw_row;
    if (!raw) return {};
    return typeof raw === 'string' ? JSON.parse(raw) : raw;
  } catch (e) {
    return {};
  }
}

function rawFieldValue(row, keys) {
  const raw = parsedRawRow(row);
  for (const k of keys) {
    if (raw[k] != null && raw[k] !== '') return String(raw[k]).trim();
  }
  for (const [k, v] of Object.entries(raw)) {
    if (v == null || v === '') continue;
    const lk = String(k).toLowerCase();
    for (const want of keys) {
      if (lk.includes(String(want).toLowerCase())) return String(v).trim();
    }
  }
  return null;
}

function normalizeYesNo(val) {
  if (val == null || val === '') return null;
  const s = String(val).trim().toLowerCase();
  if (/^(y|yes|true|1)$/i.test(s)) return 'Y';
  if (/^(n|no|false|0)$/i.test(s)) return 'N';
  if (/^no$/i.test(s)) return 'No';
  return String(val).trim();
}

function enrichAnalyticsRow(row, outageRows) {
  const classified =
    typeof classifyIncidentRow === 'function' ? classifyIncidentRow(row) : {};
  const o = { ...row, ...classified };
  if (!o.third_party || o.third_party === 'N/A') {
    o.third_party = inferThirdPartyFromSubject(o.subject) || o.third_party || 'N/A';
  }
  if (!o.issue_category) o.issue_category = inferIssueCategoryFromRow(o);
  if (!o.cause_segment && typeof classifyCauseSegmentKey === 'function') {
    o.cause_segment = classifyCauseSegmentKey(o);
  }
  if (!o.product && outageRows?.length) {
    const tid = String(o.ticket_id || '').replace(/\D/g, '');
    const match = outageRows.find((r) => {
      const link = String(r.FR_incident_link ?? r.fr_incident_link ?? '');
      return tid && link.includes(tid);
    });
    if (match) {
      o.product =
        match.Product ??
        match.product ??
        (typeof normalizeProductLabelForChart === 'function'
          ? normalizeProductLabelForChart(match)
          : null);
    }
  }
  if (!o.product) o.product = 'Unknown';
  o.status_page_flag =
    normalizeYesNo(
      rawFieldValue(o, ['Status page', 'Status Page', 'status_page', 'Statuspage']),
    ) || (/\bstatus\s*page\b/i.test(String(o.subject || '')) ? 'Y' : 'No');
  o.mom_presented_flag =
    normalizeYesNo(
      rawFieldValue(o, [
        'Presented in MOM',
        'presented_in_mom',
        'MOM',
        'Presented in Mom',
      ]),
    ) || 'N';
  return o;
}

function aggregateAnalyticsField(rows, field) {
  const buckets = new Map();
  for (const r of rows) {
    const v = String(r[field] || 'Unknown').trim() || 'Unknown';
    buckets.set(v, (buckets.get(v) || 0) + 1);
  }
  return [...buckets.entries()].sort((a, b) => b[1] - a[1]);
}

function aggregateAnalyticsByMonth(rows) {
  const MONTH_SHORT = [
    'Jan',
    'Feb',
    'Mar',
    'Apr',
    'May',
    'Jun',
    'Jul',
    'Aug',
    'Sep',
    'Oct',
    'Nov',
    'Dec',
  ];
  const buckets = new Map();
  for (const r of rows) {
    const ep = analyticsEpoch(r);
    if (!ep) continue;
    const d = new Date(ep * 1000);
    const key = `${MONTH_SHORT[d.getUTCMonth()]} ${d.getUTCFullYear()}`;
    buckets.set(key, (buckets.get(key) || 0) + 1);
  }
  return [...buckets.entries()].sort((a, b) => {
    const parseKey = (k) => {
      const [mon, yr] = k.split(' ');
      const mi = MONTH_SHORT.indexOf(mon);
      return Date.parse(`${yr}-${String(mi + 1).padStart(2, '0')}-01`);
    };
    return parseKey(a[0]) - parseKey(b[0]);
  });
}

function analyticsKpis(rows) {
  const total = rows.length;
  const p0 = rows.filter((r) => /^urgent$/i.test(String(r.priority || ''))).length;
  const open = rows.filter((r) => !/resolved|closed/i.test(String(r.status || ''))).length;
  const closed = rows.filter((r) => /resolved|closed/i.test(String(r.status || ''))).length;
  return { total, p0, open, closed };
}

/** Which dashboard widget the user asked for (one reply = one widget). */
function parseDashboardWidget(text) {
  const t = String(text || '').toLowerCase();

  if (/\b(p0\s+outages?|urgent\s+(?:priority|outages?))\b/i.test(t)) return 'kpi_p0';
  if (/\bopen\s+mim\b/i.test(t)) return 'kpi_open_mim';
  if (/\bclosed\s+mims?\b/i.test(t)) return 'kpi_closed_mim';
  if (/\b(mim\s+by\s+noc|total\s+tickets?)\b/i.test(t)) return 'kpi_mim_by_noc';

  if (/\b(status\s+page|statuspage)\b/i.test(t)) return 'status_page';
  if (/\b(presented\s+in\s+mom|mom\s+presented)\b/i.test(t)) return 'presented_in_mom';

  if (/\b(issue\s+category|category\s+split)\b/i.test(t)) return 'issue_category';
  if (/\b(third\s+party\s+split|vendor\s+split)\b/i.test(t)) return 'third_party_split';
  if (/\b(product\s+split)\b/i.test(t)) return 'product_split';
  if (/\b(monthly\s+trend|month\s+wise|by\s+month)\b/i.test(t)) return 'monthly_trend';

  if (/\b(major\s+outages?(?:\s+202\d)?|analytics\s+dashboard|outages?\s+dashboard)\b/i.test(t)) {
    return 'dashboard_overview';
  }

  return null;
}

function dashboardWidgetChartMode(widget) {
  const map = {
    monthly_trend: 'by_month',
    product_split: 'by_product',
    issue_category: 'by_issue_category',
    third_party_split: 'by_third_party',
    kpi_p0: 'kpi_only',
    kpi_open_mim: 'kpi_only',
    kpi_closed_mim: 'kpi_only',
    kpi_mim_by_noc: 'kpi_only',
    status_page: 'by_binary',
    presented_in_mom: 'by_binary',
    dashboard_overview: 'kpi_overview',
  };
  return map[widget] || 'by_month';
}

function formatBreakdownLines(sorted, total) {
  return sorted
    .map(([k, n]) => {
      const pct = total ? ((n / total) * 100).toFixed(2) : '0.00';
      return `${k}: ${n} (${pct}%)`;
    })
    .join('\n');
}

function quickChartUrl(chartConfig, w, h) {
  const width = w || 900;
  const height = h || 460;
  return (
    'https://quickchart.io/chart?format=png&w=' +
    width +
    '&h=' +
    height +
    '&c=' +
    encodeURIComponent(JSON.stringify(chartConfig))
  );
}

function buildDonutChart(sorted, title) {
  const total = sorted.reduce((s, [, n]) => s + n, 0);
  const colors = [
    '#3b82f6',
    '#60a5fa',
    '#34d399',
    '#fbbf24',
    '#f87171',
    '#a78bfa',
    '#94a3b8',
    '#fb923c',
    '#2dd4bf',
    '#e879f9',
  ];
  return {
    type: 'doughnut',
    data: {
      labels: sorted.map(([k]) => k),
      datasets: [
        {
          data: sorted.map(([, n]) => n),
          backgroundColor: sorted.map((_, i) => colors[i % colors.length]),
        },
      ],
    },
    options: {
      title: { display: true, text: `${title} (total: ${total})` },
      legend: { display: true, position: 'right' },
      plugins: { datalabels: { display: false } },
    },
  };
}

function buildMonthlyTrendChart(sorted, title) {
  const maxCount = Math.max(1, ...sorted.map(([, n]) => n));
  return {
    type: 'bar',
    data: {
      labels: sorted.map(([p]) => p),
      datasets: [
        {
          label: 'Count',
          data: sorted.map(([, n]) => n),
          backgroundColor: 'rgba(99, 102, 241, 0.9)',
        },
      ],
    },
    options: {
      title: { display: true, text: title },
      legend: { display: false },
      plugins: {
        datalabels: {
          display: true,
          anchor: 'end',
          align: 'top',
          color: '#333',
          font: { size: 12, weight: 'bold' },
          formatter: (v) => (v == null ? '' : String(v)),
        },
      },
      scales: {
        yAxes: [
          {
            ticks: {
              beginAtZero: true,
              precision: 0,
              max: maxCount + Math.max(1, Math.ceil(maxCount * 0.15)),
            },
            scaleLabel: { display: true, labelString: 'Count' },
          },
        ],
      },
    },
  };
}

