/** Cause/segment questions e.g. "how many incidents due to deployments for 2026". */
function buildSegmentQueryReply(segmentFilter, aRows, opts) {
  const options = opts || {};
  const segmentKey = segmentFilter?.key;
  const segmentLabel = segmentFilter?.label || segmentKey || 'segment';
  const rangeLabelRaw = options.rangeLabelRaw || 'selected period';
  const rangeLabel = options.rangeLabel || rangeLabelRaw;
  const filtered = filterRowsBySegmentKey(aRows, segmentKey);
  const count = filtered.length;
  const footer = '\n\n(Chart image is included in this Slack reply below.)';
  const sourceNote = `Source: MIM_Analytics_export · cause_segment=${segmentKey}`;

  if (!count) {
    return {
      status: 'no_incidents_in_range',
      notice: `0 matches for *${segmentLabel}* in *${rangeLabelRaw}*.`,
      reply:
        `*0 incidents* due to *${segmentLabel}* for *${rangeLabelRaw}*.\n\n` +
        `Searched pre-classified analytics data (${sourceNote}). ` +
        `Other causes: ${typeof listKnownSegmentLabels === 'function' ? listKnownSegmentLabels() : 'deployment, third-party, infra, …'}.`,
      chartUrl: null,
      chartDataSummary: [],
      chartMode: 'by_month',
    };
  }

  const headline = `*${count} incident(s) due to ${segmentLabel}* for *${rangeLabelRaw}*.`;
  const wantsChart =
    options.wantsChart ||
    options.yearOnly ||
    /\b(chart|trend|graph|visuali[sz]e|breakdown)\b/i.test(String(options.userText || ''));

  if (wantsChart) {
    const sorted = aggregateAnalyticsByMonth(filtered);
    const chartConfig = buildMonthlyTrendChart(
      sorted,
      `${segmentLabel} — ${rangeLabel}`,
    );
    const monthLines = sorted.map(([p, n]) => `${p}: ${n}`).join('\n');
    return {
      status: 'ok_segment_analytics',
      notice: `${sourceNote} · ${count} ticket(s)`,
      reply:
        headline +
        '\n\n*By month:*\n' +
        (monthLines || '(no dated rows)') +
        footer,
      chartUrl: quickChartUrl(chartConfig),
      chartDataSummary: sorted.map(([p, n]) => ({ period: p, incident_count: n })),
      chartMode: 'by_month',
    };
  }

  const sample = filtered.slice(0, 8).map((r) => {
    const id = r.ticket_display_id || r.ticket_id || '';
    const sub = String(r.subject || '').slice(0, 60);
    return `${id}${sub ? ' · ' + sub : ''}`;
  });

  return {
    status: 'ok_segment_analytics',
    notice: sourceNote,
    reply:
      headline +
      '\n\n' +
      (sample.length ? '*Sample tickets:*\n' + sample.join('\n') : '') +
      '\n\n_Ask for a chart with e.g. "deployments trend for 2026"._',
    chartUrl: null,
    chartDataSummary: [{ segment: segmentKey, incident_count: count }],
    chartMode: 'count_only',
  };
}

