function escapeRegExp(s) {
  return String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/** Product column(s) on Outages_data / MIM_Ticket_id (incl. MIM_type). */
function productRawFromRow(r) {
  if (!r || typeof r !== 'object') return '';
  const parts = [];
  for (const [k, v] of Object.entries(r)) {
    if (v == null || v === '') continue;
    const lk = String(k).toLowerCase();
    if (
      lk === 'product' ||
      lk === 'products' ||
      lk === 'mim_type' ||
      lk === 'mim type' ||
      lk === 'impacted_product' ||
      lk === 'service' ||
      lk === 'product_name'
    ) {
      parts.push(String(v));
    }
  }
  return parts.join(' ').trim();
}

function productBlobFromRow(r) {
  const raw = productRawFromRow(r);
  if (!raw) return '';
  return raw.toLowerCase();
}

function buildProductFilter(productDef) {
  const patterns = new Set();
  patterns.add(productDef.key);
  for (const alias of productDef.aliases) {
    patterns.add(String(alias).toLowerCase().replace(/\s+/g, ''));
    patterns.add(String(alias).toLowerCase().trim());
  }
  return {
    key: productDef.key,
    label: productDef.label,
    matchPatterns: [...patterns].filter(Boolean),
  };
}

function rowMatchesProductFilter(row, filter) {
  if (!filter || !filter.matchPatterns?.length) return true;
  const blob = productBlobFromRow(row);
  if (!blob) return false;
  const compact = blob.replace(/[^a-z0-9]+/g, '');
  for (const pat of filter.matchPatterns) {
    const p = String(pat).toLowerCase();
    const pc = p.replace(/[^a-z0-9]+/g, '');
    if (blob.includes(p) || (pc.length >= 4 && compact.includes(pc))) return true;
  }
  return false;
}

/** Longest alias wins (freshservice before fresh). */
function parseProductFilter(text) {
  const lower = String(text || '').toLowerCase();
  let best = null;
  let bestLen = 0;
  for (const def of FRESH_PRODUCTS) {
    for (const alias of def.aliases) {
      const re = new RegExp('\\b' + escapeRegExp(alias) + '\\b', 'i');
      if (re.test(lower) && alias.length > bestLen) {
        best = def;
        bestLen = alias.length;
      }
    }
  }
  return best ? buildProductFilter(best) : null;
}

function listKnownProductLabels() {
  return FRESH_PRODUCTS.map((p) => p.label).join(', ');
}

/** Canonical Freshworks product label for charts/tables. */
function normalizeProductLabelForChart(row) {
  const raw = productRawFromRow(row);
  if (!raw) return 'Unknown product';
  const compact = raw.toLowerCase().replace(/[^a-z0-9]+/g, '');
  let best = null;
  let bestLen = 0;
  for (const def of FRESH_PRODUCTS) {
    for (const alias of def.aliases) {
      const ac = alias.toLowerCase().replace(/\s+/g, '');
      if (compact.includes(ac) && ac.length > bestLen) {
        best = def.label;
        bestLen = ac.length;
      }
    }
  }
  if (best) return best;
  const s = String(raw).trim();
  return s.length > 36 ? s.slice(0, 34) + '…' : s;
}

/** Finer bucket when Product/MIM_type has more detail than canonical name. */
function chartProductGroupLabel(row) {
  const raw = productRawFromRow(row);
  if (!raw) return 'Unknown product';
  const parts = String(raw)
    .split(/[,;/|]+/)
    .map((p) => p.trim())
    .filter(Boolean);
  if (parts.length > 1) return parts[0].length > 36 ? parts[0].slice(0, 34) + '…' : parts[0];
  const canonical = normalizeProductLabelForChart(row);
  const rawShort = String(raw).trim();
  if (rawShort && rawShort.toLowerCase() !== canonical.toLowerCase()) {
    return rawShort.length > 36 ? rawShort.slice(0, 34) + '…' : rawShort;
  }
  return canonical;
}


