const SEGMENT_FIELD_KEYS = [
  'root_cause',
  'Root_cause',
  'root cause',
  'resolution',
  'Resolution',
  'description',
  'Description',
  'problem',
  'Problem',
  'customer_impact',
  'Customer_impact',
  'impact',
  'Impact',
  'incident_type',
  'Incident_type',
  'reason',
  'Reason',
  'cause',
  'Cause',
  'cause_category',
  'Cause_category',
  'mim_type',
  'MIM_type',
  'category',
  'Category',
  'notes',
  'Notes',
  'summary',
  'Summary',
];

function segmentSearchBlob(row) {
  if (!row || typeof row !== 'object') return '';
  const parts = [];
  for (const k of SEGMENT_FIELD_KEYS) {
    const v = row[k];
    if (v != null && v !== '') parts.push(String(v));
  }
  for (const [k, v] of Object.entries(row)) {
    if (v == null || v === '') continue;
    const lk = String(k).toLowerCase();
    if (
      /cause|reason|resolution|description|problem|impact|type|category|deploy|root/.test(
        lk,
      )
    ) {
      parts.push(String(v));
    }
  }
  return parts.join(' ').toLowerCase();
}

function rowMatchesSegment(row, segment) {
  if (!segment) return true;
  const blob = segmentSearchBlob(row);
  if (!blob) return false;
  for (const re of segment.textPatterns || []) {
    if (re.test(blob)) return true;
  }
  return false;
}

function escapeSegRe(s) {
  return String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/** Parse cause segment from user message (e.g. "due to deployments for 2026"). */
function parseSegmentFilter(text) {
  const lower = String(text || '').toLowerCase();
  const dueTo = lower.match(
    /\b(?:due\s+to|because\s+of|caused\s+by|related\s+to|from|owing\s+to)\s+([a-z0-9\s\-/]+?)(?:\s+for\b|\s+in\b|\s+during\b|\s+in\s+20\d{2}|$|\?)/i,
  );
  const searchBlob = dueTo ? dueTo[1].trim() : lower;

  let best = null;
  let bestScore = 0;
  for (const seg of CAUSE_SEGMENTS) {
    for (const phrase of seg.queryPhrases) {
      const re = new RegExp('\\b' + escapeSegRe(phrase) + '\\b', 'i');
      if (re.test(searchBlob) || re.test(lower)) {
        const score = phrase.length;
        if (score > bestScore) {
          best = seg;
          bestScore = score;
        }
      }
    }
  }
  if (!best) return null;
  return {
    key: best.key,
    label: best.label,
    segment: best,
  };
}

function asksCauseSegmentQuery(text) {
  const t = String(text || '').toLowerCase();
  if (parseSegmentFilter(text)) return true;
  return (
    /\b(due\s+to|because\s+of|caused\s+by|related\s+to)\b/i.test(t) &&
    /\b(incident|outage|mim)\b/i.test(t)
  );
}

function listKnownSegmentLabels() {
  return CAUSE_SEGMENTS.map((s) => s.label).join(', ');
}

/** Classify row into a display bucket (for multi-cause charts). */
function classifyRowCauseLabel(row) {
  for (const seg of CAUSE_SEGMENTS) {
    if (rowMatchesSegment(row, seg)) return seg.label;
  }
  const blob = segmentSearchBlob(row);
  if (!blob) return 'Unknown cause';
  const short = blob.slice(0, 48).trim();
  return short.length > 40 ? short.slice(0, 38) + '…' : short || 'Unknown cause';
}


/**
 * Classify MIM / outage rows at ingest time so Slack queries hit stored dimensions.
 * Used by: sync-analytics-export.js, analytics-dashboard.js
 */

const ISSUE_CATEGORY_BY_SEGMENT = {
  deployment: 'Deployment',
  third_party: 'Third Party',
  infrastructure: 'Infra',
  configuration: 'Configuration',
  security: 'Spam/DDOS',
  maintenance: 'Maintenance',
  other: 'Other',
};

function parsedRawObject(row) {
  try {
    const raw = row?.raw_row ?? row?.rawRow;
    if (!raw) return {};
    return typeof raw === 'string' ? JSON.parse(raw) : raw;
  } catch (e) {
    return {};
  }
}

function exportField(row, names) {
  const raw = parsedRawObject(row);
  for (const n of names) {
    if (raw[n] != null && raw[n] !== '') return String(raw[n]).trim();
  }
  for (const [k, v] of Object.entries(raw)) {
    if (v == null || v === '') continue;
    const lk = String(k).toLowerCase();
    for (const n of names) {
      if (lk.includes(String(n).toLowerCase())) return String(v).trim();
    }
  }
  return null;
}

function textBlobForClassify(row) {
  const parts = [];
  if (row?.subject) parts.push(String(row.subject));
  if (row?.issue_category) parts.push(String(row.issue_category));
  if (row?.description) parts.push(String(row.description));
  if (row?.root_cause) parts.push(String(row.root_cause));
  if (typeof segmentSearchBlob === 'function') {
    parts.push(segmentSearchBlob(row));
  }
  const raw = parsedRawObject(row);
  for (const v of Object.values(raw)) {
    if (v != null && v !== '') parts.push(String(v));
  }
  return parts.join(' ').toLowerCase();
}

/** Primary cause segment key (deployment, third_party, infrastructure, …). */
function classifyCauseSegmentKey(row) {
  if (row?.cause_segment) return String(row.cause_segment);
  if (typeof rowMatchesSegment === 'function' && typeof CAUSE_SEGMENTS !== 'undefined') {
    for (const seg of CAUSE_SEGMENTS) {
      if (rowMatchesSegment(row, seg)) return seg.key;
    }
  }
  const blob = textBlobForClassify(row);
  if (/\bdeploy/.test(blob)) return 'deployment';
  if (/\bthird[\s-]?party\b|\bvendor\b|cloudflare|azure\b|aws\b/.test(blob)) {
    return 'third_party';
  }
  if (/\binfra|network|database\b|capacity|hardware/.test(blob)) return 'infrastructure';
  if (/\bmisconfig|config(?:uration)?\s+error/.test(blob)) return 'configuration';
  if (/\bddos|spam|attack|security|breach/.test(blob)) return 'security';
  if (/\bmaintenance\b|planned\s+(?:outage|downtime)/.test(blob)) return 'maintenance';
  if (/\bcode\b|bug|exception/.test(blob)) return 'other';
  return 'other';
}

function issueCategoryLabelFromKey(segmentKey) {
  return ISSUE_CATEGORY_BY_SEGMENT[segmentKey] || 'Other';
}

function inferThirdPartyVendor(row) {
  const fromExport =
    exportField(row, ['Third Party', 'third_party', 'Vendor', 'vendor']) ||
    row?.third_party;
  if (fromExport && fromExport !== 'N/A') return fromExport;
  const blob = textBlobForClassify(row);
  const vendors = [
    ['Cloudflare', /\bcloudflare\b/i],
    ['Azure', /\bazure\b/i],
    ['AWS', /\baws\b/i],
    ['META', /\bmeta\b/i],
    ['Microsoft', /\bmicrosoft\b/i],
    ['Google', /\bgoogle\b|\bgcp\b/i],
  ];
  for (const [name, re] of vendors) {
    if (re.test(blob)) return name;
  }
  return null;
}

function normalizeYesNoFlag(val, subject) {
  if (val != null && val !== '') {
    const s = String(val).trim().toLowerCase();
    if (/^(y|yes|true|1)$/i.test(s)) return 'Y';
    if (/^(n|no|false|0)$/i.test(s)) return 'N';
    return String(val).trim();
  }
  if (/\bstatus\s*page\b/i.test(String(subject || ''))) return 'Y';
  return null;
}

/** Full classification written to MIM_Analytics_export at sync. */
function classifyIncidentRow(row) {
  const subject = row?.subject ?? row?.Subject ?? '';
  const cause_segment = classifyCauseSegmentKey(row);
  const fromExport = exportField(row, [
    'Issue Category',
    'issue_category',
    'Category',
    'category',
    'Root Cause',
    'root_cause',
  ]);
  let issue_category =
    fromExport ||
    row?.issue_category ||
    issueCategoryLabelFromKey(cause_segment);
  if (/^deployment/i.test(issue_category)) issue_category = 'Deployment';
  if (/^third/i.test(issue_category)) issue_category = 'Third Party';
  if (/^infra/i.test(issue_category)) issue_category = 'Infra';

  const third_party = inferThirdPartyVendor(row);
  const status_page =
    exportField(row, ['Status page', 'Status Page', 'status_page']) ||
    (/\bstatus\s*page\b/i.test(subject) ? 'Y' : 'No');
  const mom_presented = exportField(row, [
    'Presented in MOM',
    'presented_in_mom',
    'MOM',
  ]);

  return {
    cause_segment,
    issue_category,
    third_party: third_party || 'N/A',
    status_page_flag: normalizeYesNoFlag(status_page, subject) || 'No',
    mom_presented_flag: normalizeYesNoFlag(mom_presented, subject) || 'N',
    product:
      exportField(row, ['Product', 'product', 'MIM_type', 'Impacted Product']) ||
      row?.product ||
      null,
  };
}

function analyticsRowMatchesSegmentKey(row, segmentKey) {
  if (!segmentKey) return true;
  const stored = String(row?.cause_segment || '').toLowerCase();
  if (stored && stored === String(segmentKey).toLowerCase()) return true;
  if (typeof rowMatchesSegment === 'function' && typeof CAUSE_SEGMENTS !== 'undefined') {
    const seg = CAUSE_SEGMENTS.find((s) => s.key === segmentKey);
    if (seg && rowMatchesSegment(row, seg)) return true;
  }
  const cat = String(row?.issue_category || '').toLowerCase();
  const want = issueCategoryLabelFromKey(segmentKey).toLowerCase();
  if (cat && want && cat === want) return true;
  if (segmentKey === 'deployment' && /\bdeploy/.test(cat)) return true;
  if (segmentKey === 'third_party' && /third/.test(cat)) return true;
  if (segmentKey === 'infrastructure' && /infra/.test(cat)) return true;
  return classifyCauseSegmentKey(row) === segmentKey;
}

function filterRowsBySegmentKey(rows, segmentKey) {
  if (!segmentKey) return rows;
  return rows.filter((r) => analyticsRowMatchesSegmentKey(r, segmentKey));
}


