/** Cause/segment questions e.g. "how many incidents due to deployments for 2026". */
function buildSegmentQueryReply(segmentFilter, aRows, opts) {
  const options = opts || {};
  const segmentKey = segmentFilter?.key;
  const segmentLabel = segmentFilter?.label || segmentKey || 'segment';
  const rangeLabelRaw = options.rangeLabelRaw || 'selected period';
  const rangeLabel = options.rangeLabel || rangeLabelRaw;
  const filtered = filterRowsBySegmentKey(aRows, segmentKey);
  const count = filtered.length;
  const footer = '\n\n(Chart image is included in this Slack reply below.)';
  const sourceNote = `Source: MIM_Analytics_export · cause_segment=${segmentKey}`;

  if (!count) {
    return {
      status: 'no_incidents_in_range',
      notice: `0 matches for *${segmentLabel}* in *${rangeLabelRaw}*.`,
      reply:
