/** Bare FS numbers: small = minutes; 1441–604800 often seconds (e.g. 1800 → 30 min). */
function bareNumberToMinutes(n) {
  if (!Number.isFinite(n) || n < 0) return null;
  if (n <= 1440) return Math.round(n);
  if (n <= 604800) return Math.round(n / 60);
  return null;
}

/** Drop bad parses / wall-clock outliers so charts and tables are not skewed. */
function sanitizeMetricMinutes(m) {
  if (m == null || !Number.isFinite(m)) return null;
  let v = Math.round(m);
  if (v > 10080) return null;
  if (v > 2880 && v <= 604800) v = Math.round(v / 60);
  if (v > 2880) return null;
  return v;
}

function median(nums) {
  const v = nums.filter((n) => n != null && Number.isFinite(n)).sort((a, b) => a - b);
  if (!v.length) return null;
  const mid = Math.floor(v.length / 2);
  return v.length % 2 ? v[mid] : Math.round((v[mid - 1] + v[mid]) / 2);
}

const SLACK_USER_ID_RE = /^U[A-Z0-9]{6,}$/i;

function nameFromValue(v) {
  if (v == null || v === '') return null;
  if (typeof v === 'object') {
    if (v.name && !SLACK_USER_ID_RE.test(String(v.name))) return String(v.name).trim();
    const full = [v.first_name, v.last_name].filter(Boolean).join(' ').trim();
    if (full) return full;
    return null;
  }
  const s = String(v).trim();
  if (!s || SLACK_USER_ID_RE.test(s)) return null;
  if (/^\d+$/.test(s)) return null;
  return s;
}

/** Human assignee from Freshservice ticket (not Slack User_id). */
function assigneeNameFromTicket(ticket) {
  if (!ticket || ticket.error) return null;
  if (ticket.assignee_full_name) return nameFromValue(ticket.assignee_full_name);
  for (const key of [
    'responder_name',
    'agent_name',
    'assigned_to_name',
    'requester_name',
  ]) {
    const n = nameFromValue(ticket[key]);
    if (n) return n;
  }
  const cf = ticket.custom_fields_full || ticket.custom_fields_metrics || {};
  for (const [k, val] of Object.entries(cf)) {
    const lk = normalizeFieldKey(k);
    if (/assign|owner|agent|responder|mim|commander|lead|manager/i.test(lk)) {
      const n = nameFromValue(val);
      if (n) return n;
    }
  }
  return null;
}

function mimTicketIdFromRow(r) {
  const v = r?.Ticket_field ?? r?.ticket_field;
