function slackThreadKey(urlOrTs) {
  const s = String(urlOrTs || '');
  const m = s.match(/p(\d{10,16})/) || s.match(/thread_ts=([\d.]+)/i);
  if (!m) return '';
  return String(m[1]).replace(/\./g, '').slice(0, 16);
}

function isMimRow(r) {
  if (!r || typeof r !== 'object' || r.error) return false;
  if (r._mysql_source === 'MIM_Ticket_id') return true;
