/** Pull MIM rows from Attach DB, Resolve payload, and MySQL node output. */
function loadAllMimRows(base) {
  const uniq = new Map();
  const add = (r) => {
    if (!isMimRow(r)) return;
    const norm = { ...r, _mysql_source: 'MIM_Ticket_id' };
    const tid = mimTicketIdFromRow(norm);
    const key = tid || `row_${uniq.size}`;
    if (!uniq.has(key)) uniq.set(key, norm);
  };
  (base.dbFwRows || []).forEach(add);
  (base.mimTicketDbRows || []).forEach(add);
  try {
    $('MySQL: MIM_Ticket_id')
      .all()
      .forEach((item) => add(item.json));
  } catch (e) {
    /* branch did not run */
  }
  try {
    const attach = $('Code: Attach DB snapshot').first().json;
    (attach.dbFwRows || []).forEach(add);
  } catch (e) {
    /* */
  }
  return [...uniq.values()];
}

function mimMatchesRange(m, reportRows, ticketIdsInRange) {
  const tid = mimTicketIdFromRow(m);
  if (tid && ticketIdsInRange.has(tid)) return true;
  for (const row of reportRows) {
    const link = String(row?.FR_incident_link ?? row?.fr_incident_link ?? '');
    if (tid && link.includes(tid)) return true;
    const mThread = slackThreadKey(m.Slack_thread || m.slack_thread);
    const oThread = slackThreadKey(row.slack_thread || row.Slack_thread);
    if (mThread && oThread && mThread === oThread) return true;
    if (mThread && String(m.Slack_thread || '').includes(oThread) && oThread) return true;
  }
  return false;
}

