function buildBarCountChart(sorted, rangeLabel, opts) {
  const options = opts || {};
  const dimension = options.dimension || 'priority';
  const datasetLabel = options.datasetLabel || 'Incidents';
  const yAxisLabel = options.yAxisLabel || 'Incident count';
  const titlePrefix =
    options.titlePrefix ||
    (dimension === 'product' ? 'Incidents by product' : 'Incidents by priority');
  const labels = sorted.map(([p]) => (p.length > 28 ? p.slice(0, 26) + '…' : p));
  const maxCount = Math.max(1, ...sorted.map(([, n]) => n));
  const chartTitle =
    dimension === 'period'
      ? rangeLabel
        ? `${titlePrefix} — ${rangeLabel}`
        : titlePrefix
      : rangeLabel
        ? `${titlePrefix} — ${rangeLabel}${options.titleSuffix || ''}`
        : `${titlePrefix}${options.titleSuffix || ''}`;
  const chartConfig = {
    type: 'bar',
    data: {
      labels,
      datasets: [
        {
          label: datasetLabel,
          data: sorted.map(([, n]) => n),
          backgroundColor:
            dimension === 'product'
              ? 'rgba(16, 185, 129, 0.88)'
              : dimension === 'period'
                ? 'rgba(245, 158, 11, 0.9)'
                : 'rgba(99, 102, 241, 0.9)',
        },
      ],
    },
    options: {
      title: { display: true, text: chartTitle },
      legend: { display: true },
      plugins: {
        datalabels: {
          display: true,
          anchor: 'end',
          align: 'top',
          color: '#333',
          font: { size: 12, weight: 'bold' },
          formatter: (v) => (v == null ? '' : String(v)),
        },
      },
      scales: {
        yAxes: [
          {
            ticks: {
              beginAtZero: true,
              precision: 0,
              max: maxCount + Math.max(1, Math.ceil(maxCount * 0.15)),
            },
            scaleLabel: { display: true, labelString: yAxisLabel },
          },
        ],
      },
    },
  };
  const chartDataSummary = sorted.map(([key, n]) => {
    if (dimension === 'product') {
      return { product: key, incident_count: n };
    }
    if (dimension === 'period') {
      return { period: key, incident_count: n };
    }
    return { priority: key, mim_count: n };
  });
  return { chartConfig, chartDataSummary };
}

