/** Parse Freshservice/custom field values into minutes (number, "5", "1 min", "2h 30m"). */
function parseMinutesValue(v) {
  if (v == null || v === '') return null;
  if (typeof v === 'number' && Number.isFinite(v)) return bareNumberToMinutes(v);
  const s = String(v).trim().toLowerCase();
  if (!s) return null;
  const plain = Number(s);
  if (Number.isFinite(plain) && !/[a-z]/.test(s.replace(/\./g, ''))) {
    return bareNumberToMinutes(plain);
  }
  let total = 0;
  let matched = false;
  const day = s.match(/(\d+(?:\.\d+)?)\s*(?:d|day|days)\b/);
  const hr = s.match(/(\d+(?:\.\d+)?)\s*(?:h|hr|hrs|hour|hours)\b/);
  const min = s.match(/(\d+(?:\.\d+)?)\s*(?:m|min|mins|minute|minutes)\b/);
  if (day) {
    total += Number(day[1]) * 1440;
    matched = true;
  }
  if (hr) {
    total += Number(hr[1]) * 60;
    matched = true;
  }
  if (min) {
    total += Number(min[1]);
    matched = true;
  }
  if (matched) return Math.round(total);
  const onlyNum = s.match(/^(\d+(?:\.\d+)?)$/);
  return onlyNum ? bareNumberToMinutes(Number(onlyNum[1])) : null;
}

function normalizeFieldKey(k) {
  return String(k || '')
    .toLowerCase()
    .replace(/[_-]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

/** Match Freshservice custom field keys (long names must not false-match "time to detect" inside recover keys). */
function metricKindFromFieldKey(lk) {
  if (/^time\s*to\s*ack\b|^time\s*to\s*acknowledge|^time\s*to\s*respond\b|^mtta\b/.test(lk)) {
    return 'mtta';
  }
  if (
    /^time\s*to\s*recover\b|^time\s*to\s*resolve\b|^time\s*to\s*restor\b|^mttr\b/.test(
      lk,
    )
  ) {
    return 'mttr';
  }
  if (/^time\s*to\s*detect\b|^mttd\b|^time\s*to\s*discover/.test(lk)) {
    return 'mttd';
  }
  return null;
}

/** Scan custom_fields and any object for time to detect / ack / recover (many label variants). */
function extractOperationalMetrics(source) {
  const out = {};
  const visit = (obj) => {
    if (!obj || typeof obj !== 'object') return;
    for (const [k, v] of Object.entries(obj)) {
      if (v == null || v === '') continue;
      const lk = normalizeFieldKey(k);
      const mins = sanitizeMetricMinutes(parseMinutesValue(v));
      if (mins == null) continue;
      const kind = metricKindFromFieldKey(lk);
      if (kind === 'mtta') out.mtta_minutes = mins;
      else if (kind === 'mttd') out.mttd_minutes = mins;
      else if (kind === 'mttr') out.mttr_minutes = mins;
    }
  };
  const t = source?.ticket || source;
  if (t?.custom_fields) visit(t.custom_fields);
  if (source?.custom_fields) visit(source.custom_fields);
  if (source?.custom_fields_full) visit(source.custom_fields_full);
  if (source?.custom_fields_metrics) visit(source.custom_fields_metrics);
  visit(source);
  return out;
}

function slimTicket(raw) {
  const t = raw?.ticket || raw;
  if (!t || typeof t !== 'object') return raw;
  const cf = t.custom_fields && typeof t.custom_fields === 'object' ? t.custom_fields : {};
  const metrics = {};
  for (const [k, v] of Object.entries(cf)) {
    if (v == null || v === '') continue;
    const lk = normalizeFieldKey(k);
    if (
      /time\s*to\s*(detect|ack|acknowledge|recover|resolve)/i.test(lk) ||
      /mtt[ard]\b|impact/i.test(lk)
    ) {
      metrics[k] = v;
    }
  }
  const operational_metrics = extractOperationalMetrics({ ticket: t, custom_fields: cf });
  const slim = {
    id: t.id,
    display_id: t.display_id,
    subject: t.subject,
    status: t.status,
    priority: t.priority,
    type: t.type,
    created_at: t.created_at,
    updated_at: t.updated_at,
    resolved_at: t.resolved_at,
    closed_at: t.closed_at,
    custom_fields_metrics: metrics,
    custom_fields_full: cf,
    description_text:
      typeof t.description_text === 'string'
        ? t.description_text.slice(0, 2000)
        : undefined,
    ticket_url: t.id
      ? `https://freshworks.freshservice.com/a/tickets/${t.id}?current_tab=details`
      : undefined,
    operational_metrics,
    responder_name: nameFromValue(t.responder),
    agent_name: nameFromValue(t.agent),
    requester_name: nameFromValue(t.requester),
  };
  slim.assignee_full_name = assigneeNameFromTicket(slim);
  return slim;
}

