      (j.statusCode ? `HTTP ${j.statusCode}` : null) ||
      'Freshservice request failed (check HTTP Basic Auth credential on HTTP: Freshservice ticket)';
    freshserviceTickets.push({
      requested_id: requested_id || ticketIdList[idx],
