function metricsFromTicket(ticket) {
  if (!ticket || ticket.error) return { mtta: null, mttd: null, mttr: null };
  const op = ticket.operational_metrics || extractOperationalMetrics(ticket);
  let mtta = op.mtta_minutes ?? null;
  let mttd = op.mttd_minutes ?? null;
  let mttr = op.mttr_minutes ?? null;
  const m = ticket.custom_fields_metrics || {};
  for (const [k, v] of Object.entries(m)) {
    const lk = normalizeFieldKey(k);
    const mins = sanitizeMetricMinutes(parseMinutesValue(v));
    if (mins == null) continue;
    const kind = metricKindFromFieldKey(lk);
    if (kind === 'mtta' && mtta == null) mtta = mins;
    if (kind === 'mttd' && mttd == null) mttd = mins;
    if (kind === 'mttr' && mttr == null) mttr = mins;
  }
  if (mttr == null && ticket.created_at && (ticket.resolved_at || ticket.closed_at)) {
    const a = Date.parse(ticket.created_at);
    const b = Date.parse(ticket.resolved_at || ticket.closed_at);
    if (Number.isFinite(a) && Number.isFinite(b) && b > a) {
      const wallMin = sanitizeMetricMinutes(Math.round((b - a) / 60000));
      if (wallMin != null) mttr = wallMin;
    }
  }
  return {
    mtta: sanitizeMetricMinutes(mtta),
    mttd: sanitizeMetricMinutes(mttd),
    mttr: sanitizeMetricMinutes(mttr),
  };
}

const miIdsFromText = (s) => {
