function epochFromOutageRowForReport(r) {
  const v = r?.create_epoch_date_time ?? r?.Create_epoch_date_time;
  if (v == null || v === '') return 0;
  const n = Number(v);
  if (Number.isFinite(n) && n > 1e8 && n < 1e14) {
    return n > 1e12 ? n / 1000 : n;
  }
  const d = Date.parse(String(v));
  return Number.isFinite(d) ? d / 1000 : 0;
}

function outagesInReportRange(base, range) {
  if (!range) return [];
  const productFilter = base.incidentReportProductFilter || null;
  const segmentFilter = base.incidentReportSegmentFilter || null;
  const seen = new Map();
  for (const row of loadAllOutageRows(base)) {
    const ep = epochFromOutageRowForReport(row);
    if (!ep || ep < range.from || ep > range.to) continue;
    if (productFilter && !rowMatchesProductFilter(row, productFilter)) continue;
    if (segmentFilter?.segment && !rowMatchesSegment(row, segmentFilter.segment)) continue;
    const inc = row?.incident_no ?? row?.Incident_no;
    const key = inc != null ? String(inc) : `row_${seen.size}`;
    const prev = seen.get(key);
    if (!prev || epochFromOutageRowForReport(row) >= epochFromOutageRowForReport(prev)) {
      seen.set(key, row);
    }
  }
  return [...seen.values()];
}

