      dataPlan.source === 'analytics' &&
      analyticsAll.length > 0 &&
      !!base.dashboardWidget;

    if (useAnalyticsPath) {
      let aRows = range ? analyticsRowsInRange(analyticsAll, range) : analyticsAll;
      const productFilter = base.incidentReportProductFilter || null;
      if (productFilter) {
        aRows = aRows.filter((r) => rowMatchesProductFilter(r, productFilter));
      }
      const segmentFilter = base.incidentReportSegmentFilter || null;
      const analyticsUrl =
        base.freshserviceAnalyticsReportUrl || FRESHSERVICE_ANALYTICS_REPORT_URL;
      let widgetResult;

      if (segmentFilter?.key) {
        incidentReportOutageCountFinal = filterRowsBySegmentKey(
          aRows,
          segmentFilter.key,
        ).length;
        const yearOnly =
          range && /^\d{4}$/.test(String(range.label || ''));
        const wantsChart =
          base.wantsMonthlyTrendChart ||
          chartMode === 'by_month' ||
          chartMode === 'by_year' ||
          /\b(chart|trend|graph|visuali[sz]e)\b/i.test(String(base.userText || ''));
        widgetResult = buildSegmentQueryReply(segmentFilter, aRows, {
          rangeLabel,
          rangeLabelRaw,
          wantsChart,
          yearOnly,
          userText: base.userText,
        });
      } else {
        const widget = base.dashboardWidget || 'monthly_trend';
        widgetResult = buildDashboardWidgetReply(widget, aRows, {
          rangeLabel,
          rangeLabelRaw,
          analyticsUrl,
          productLabel,
        });
        incidentReportOutageCountFinal = aRows.length;
      }

      incidentReportStatus = widgetResult.status;
      incidentReportNotice = widgetResult.notice;
      incidentReportDeterministicReply = widgetResult.reply;
      incidentReportChartUrl = widgetResult.chartUrl;
      incidentReportCountChartUrl = widgetResult.chartUrl;
      chartDataSummary = widgetResult.chartDataSummary;
      incidentReportChartMode = widgetResult.chartMode || chartMode;
      if (dataPlan.reason) {
        incidentReportNotice =
          (incidentReportNotice ? incidentReportNotice + ' ' : '') + `(${dataPlan.reason})`;
      }
    } else if (chartMode === 'by_product') {
      const byProd = new Map();
      incidentReportTable = [];
      for (const row of reportRows) {
        const label = chartProductGroupLabel(row);
        byProd.set(label, (byProd.get(label) || 0) + 1);
        incidentReportTable.push({
          incident_no: row.incident_no ?? row.Incident_no,
          product: label,
          priority: normalizeOutagePriority(row),
          chart_source: 'outages_by_product',
        });
      }

      const totalInChart = [...byProd.values()].reduce((a, b) => a + b, 0);
      if (!totalInChart) {
        incidentReportStatus = 'no_chart_data';
        incidentReportNotice = `No product labels on Outages_data rows for ${rangeLabel}.`;
        incidentReportDeterministicReply =
          `*0 incidents* with Product/MIM_type for *${rangeLabel}*.`;
      } else {
        const sorted = [...byProd.entries()].sort((a, b) => b[1] - a[1]);
        const built = buildBarCountChart(sorted, rangeLabel, {
          dimension: 'product',
          datasetLabel: 'Incidents',
          yAxisLabel: 'Incident count',
          titlePrefix: productLabel
            ? `${productLabel} incidents by product`
            : 'Incidents by product',
          titleSuffix: '',
        });
        chartDataSummary = built.chartDataSummary;
        incidentReportChartUrl =
          'https://quickchart.io/chart?format=png&w=900&h=460&c=' +
          encodeURIComponent(JSON.stringify(built.chartConfig));
        incidentReportCountChartUrl = incidentReportChartUrl;
        incidentReportStatus = 'ok_by_product';
        const productSummary = chartDataSummary
          .map((s) => `${s.product}: ${s.incident_count}`)
          .join(' | ');
        incidentReportNotice = segmentLabel
          ? `${reportRows.length} incident(s) due to *${segmentLabel}* in *${rangeLabelRaw}*; chart by Product / MIM_type.`
          : `${reportRows.length} incident(s) in ${rangeLabel}; chart grouped by Product / MIM_type from Outages_data.`;
        const countHeadline = segmentLabel
          ? `*${reportRows.length} incident(s) due to ${segmentLabel}* in Outages_data for *${rangeLabelRaw}*.`
          : productLabel
            ? `*${reportRows.length} ${productLabel} incident(s)/outage(s)* in Outages_data for *${rangeLabelRaw}*.`
            : `*${reportRows.length} outage(s)* in Outages_data for *${rangeLabel}*.`;
        const tableLines = incidentReportTable
          .slice(0, 20)
          .map(
            (r) =>
              `Inc ${r.incident_no} · ${r.product || ''} · ${r.priority || ''}`,
          )
          .join('\n');
        incidentReportDeterministicReply =
          countHeadline +
          '\n\n' +
          incidentReportNotice +
          '\n\n*By product:* ' +
          productSummary +
          (tableLines ? '\n\n' + tableLines : '') +
          '\n\n(Bar chart image is included in this Slack reply below.)';
      }
    } else if (chartMode === 'by_month' || chartMode === 'by_year') {
      const MONTH_SHORT = [
        'Jan',
        'Feb',
        'Mar',
        'Apr',
        'May',
        'Jun',
        'Jul',
        'Aug',
        'Sep',
        'Oct',
        'Nov',
        'Dec',
      ];
      const segmentFilter = base.incidentReportSegmentFilter || null;
      const useSegmentRows = !!segmentFilter?.segment;
      const allOutages = useSegmentRows ? reportRows : loadAllOutageRows(base);
      const buckets = new Map();
      const seenInc = new Set();
      incidentReportTable = [];

      const productFilter = base.incidentReportProductFilter || null;
      for (const row of allOutages) {
        const ep = epochFromOutageRowForReport(row);
        if (!useSegmentRows) {
          if (!ep || ep < range.from || ep > range.to) continue;
          if (productFilter && !rowMatchesProductFilter(row, productFilter)) continue;
          if (segmentFilter?.segment && !rowMatchesSegment(row, segmentFilter.segment)) {
            continue;
          }
        }
        const inc = row.incident_no ?? row.Incident_no;
        if (inc != null) seenInc.add(String(inc));
        const d = new Date((ep || epochFromOutageRowForReport(row)) * 1000);
        const key =
          chartMode === 'by_year'
            ? String(d.getUTCFullYear())
            : `${MONTH_SHORT[d.getUTCMonth()]} ${d.getUTCFullYear()}`;
        buckets.set(key, (buckets.get(key) || 0) + 1);
        if (useSegmentRows && incidentReportTable.length < 25) {
          incidentReportTable.push({
            incident_no: inc,
            product: chartProductGroupLabel(row),
            priority: normalizeOutagePriority(row),
            cause_match: segmentLabel,
            chart_source: 'segment_filtered',
          });
        }
      }

      const sorted = [...buckets.entries()].sort((a, b) => {
        const parseKey = (k) => {
          if (/^\d{4}$/.test(k)) return Date.parse(`${k}-06-01`);
          const [mon, yr] = k.split(' ');
          const mi = MONTH_SHORT.indexOf(mon);
          return Date.parse(`${yr}-${String(mi + 1).padStart(2, '0')}-01`);
        };
        return parseKey(a[0]) - parseKey(b[0]);
      });

      chartDataSummary = sorted.map(([period, count]) => ({
        period,
        incident_count: count,
      }));

      const analyticsUrl =
        base.freshserviceAnalyticsReportUrl || FRESHSERVICE_ANALYTICS_REPORT_URL;
      const built = buildBarCountChart(
        sorted.map(([p, n]) => [p, n]),
        rangeLabel,
        {
          dimension: 'period',
          datasetLabel: 'Incidents',
          yAxisLabel: 'Incident count',
          titlePrefix: segmentLabel
            ? `${segmentLabel} — incidents by ${chartMode === 'by_year' ? 'year' : 'month'}`
            : chartMode === 'by_year'
              ? 'Major Outages — incidents by year'
              : 'Major Outages — monthly trend',
          titleSuffix: '',
        },
      );
      built.chartConfig.data.datasets[0].backgroundColor = segmentLabel
        ? 'rgba(245, 158, 11, 0.9)'
        : 'rgba(99, 102, 241, 0.9)';
      chartDataSummary = sorted.map(([period, count]) => ({ period, incident_count: count }));

      incidentReportChartUrl =
        'https://quickchart.io/chart?format=png&w=900&h=460&c=' +
        encodeURIComponent(JSON.stringify(built.chartConfig));
      incidentReportCountChartUrl = incidentReportChartUrl;
      incidentReportStatus = segmentLabel ? 'ok_segment_trend' : 'ok_analytics_trend';
      incidentReportNotice = segmentLabel
        ? `${reportRows.length} incident(s) due to *${segmentLabel}* in *${rangeLabelRaw}* (matched in root_cause / resolution / description).`
        : `${seenInc.size} unique incident(s) in ${rangeLabel} (Outages_data). Analytics: ${analyticsUrl}`;

      const trendSummary = chartDataSummary
        .map((s) => `${s.period}: ${s.incident_count}`)
        .join(' | ');
      const trendTotal = reportRows.length || seenInc.size;
      const trendHeadline = segmentLabel
        ? `*${trendTotal} incident(s) due to ${segmentLabel}* in Outages_data for *${rangeLabelRaw}*.`
        : `*${trendTotal} outage(s)* in Outages_data for *${rangeLabel}*.`;

      incidentReportDeterministicReply =
        trendHeadline +
        '\n\n' +
        incidentReportNotice +
        '\n\n*Trend:* ' +
        trendSummary +
        '\n\n(Bar chart image is included in this Slack reply below.)';
    } else {
    const ticketIdsInRange = new Set();
    for (const row of reportRows) {
      const link = String(row?.FR_incident_link ?? row?.fr_incident_link ?? '');
      for (const tid of miIdsFromText(link)) ticketIdsInRange.add(tid);
      for (const tid of miIdsFromText(JSON.stringify(row))) ticketIdsInRange.add(tid);
    }

    const productFilter = base.incidentReportProductFilter || null;
    const allMimRows = loadAllMimRows(base);
    let chartSource = 'mim_linked';
    let mimForChart = allMimRows.filter((m) => {
      if (productFilter && !rowMatchesProductFilter(m, productFilter)) return false;
      return mimMatchesRange(m, reportRows, ticketIdsInRange);
    });

    /** Do not dump all MIM_Ticket_id rows when product/range filter applies — skews counts. */
    if (!mimForChart.length && allMimRows.length && !productFilter) {
      chartSource = 'mim_all_db';
      mimForChart = allMimRows;
    }

    const byPri = new Map();
    incidentReportTable = [];

    if (mimForChart.length) {
      for (const m of mimForChart) {
        const p = normalizeMimPriority(m);
        byPri.set(p, (byPri.get(p) || 0) + 1);
        incidentReportTable.push({
          mim_ticket_id: mimTicketIdFromRow(m),
          priority: p,
          product: m.Product ?? m.product ?? null,
          region: m.Region ?? m.region ?? null,
          chart_source: chartSource,
        });
      }
    }

    if (!byPri.size && reportRows.length) {
      chartSource = 'outages_in_range';
      for (const row of reportRows) {
        const p = normalizeOutagePriority(row);
        byPri.set(p, (byPri.get(p) || 0) + 1);
        incidentReportTable.push({
          incident_no: row.incident_no ?? row.Incident_no,
          priority: p,
          chart_source: chartSource,
        });
      }
    }

    const totalInChart = [...byPri.values()].reduce((a, b) => a + b, 0);
    if (!totalInChart) {
      incidentReportStatus = 'no_chart_data';
      incidentReportNotice = `No incidents or MIM rows to chart for ${rangeLabel}.`;
    } else if (chartSource === 'mim_linked') {
      incidentReportStatus = 'ok';
      incidentReportNotice = `${totalInChart} MIM ticket(s) in ${rangeLabel} (linked via Ticket_field / FR_incident_link), grouped by MIM_Ticket_id.Priority.`;
    } else if (chartSource === 'mim_all_db') {
      incidentReportStatus = 'ok_mim_unlinked';
      incidentReportNotice = `${totalInChart} MIM ticket(s) from MIM_Ticket_id (${allMimRows.length} rows in DB; could not link all to ${rangeLabel} outages). Chart uses MIM Priority.`;
    } else {
      incidentReportStatus = 'ok_outage_fallback';
      incidentReportNotice = `${reportRows.length} incident(s) in ${rangeLabel}; MIM_Ticket_id had ${allMimRows.length} row(s). Chart shows *incident count by Outages_data priority* (MIM link unavailable).`;
    }

    if (byPri.size) {
      const sorted = [...byPri.entries()].sort((a, b) => b[1] - a[1]);
      const suffix =
        chartSource === 'outages_in_range' ? ' (incidents)' : '';
      const built = buildMimCountChart(sorted, rangeLabel, suffix);
      chartDataSummary = built.chartDataSummary;
      incidentReportChartUrl =
        'https://quickchart.io/chart?format=png&w=900&h=460&c=' +
        encodeURIComponent(JSON.stringify(built.chartConfig));
      incidentReportCountChartUrl = incidentReportChartUrl;
      incidentReportMetricsChartUrl = null;
    }

    const countLabel =
      chartSource === 'outages_in_range' ? 'incidents' : 'MIM';
    const prioritySummary = (chartDataSummary || []).map((s) => {
      if (s.product != null) return `${s.product}: ${s.incident_count} incidents`;
      return `${s.priority}: ${s.mim_count} ${countLabel}`;
    });

    const tableLines = incidentReportTable
      .slice(0, 20)
      .map((r) => {
        if (r.mim_ticket_id) {
          const parts = [`MI-${r.mim_ticket_id}`, r.priority || ''];
          if (r.product) parts.push(String(r.product));
          if (r.region) parts.push(String(r.region));
          return parts.filter(Boolean).join(' · ');
        }
        return `Inc ${r.incident_no} · ${r.priority || ''}`;
      })
      .join('\n');

    const countHeadline = productLabel
      ? `*${reportRows.length} ${productLabel} incident(s)/outage(s)* in Outages_data for *${rangeLabelRaw}*.`
      : `*${reportRows.length} outage(s)* in Outages_data for *${rangeLabel}*.`;

    incidentReportDeterministicReply =
      countHeadline +
      '\n\n' +
      incidentReportNotice +
      '\n\n*By priority:* ' +
      (prioritySummary.length ? prioritySummary.join(' | ') : '(none)') +
      (tableLines ? '\n\n' + tableLines : '') +
      '\n\n(Bar chart image is included in this Slack reply below.)';
    }
  }
}

const ticketById = new Map();
for (const t of freshserviceTickets) {
  if (!t || t.error) continue;
  const id = String(t.id || t.display_id || '').trim();
  if (id) ticketById.set(id, t);
}

const mimTicketDbRowsEnriched = (base.mimTicketDbRows || []).map((r) =>
  enrichMimRowForPrompt(r, ticketById),
);
const focusedTid = String(
  base.focusedFreshserviceTicketId ||
    base.focusedMimRow?.Ticket_field ||
