);
const focusedMimRowEnriched = base.focusedMimRow
  ? enrichMimRowForPrompt(base.focusedMimRow, ticketById)
  : null;

return [
  {
    json: {
      ...base,
      freshserviceTickets,
      freshserviceTicketCount: freshserviceTickets.length,
      freshserviceHttpRan,
      freshserviceConfiguredOk: freshserviceTickets.some((t) => t && t.id && !t.error),
      mimTicketDbRows: mimTicketDbRowsEnriched,
      focusedMimRow: focusedMimRowEnriched,
      focusedMimAssignee: focusedMimAssignee || focusedMimRowEnriched?.mim_assignee_full_name || null,
      incidentReportChartUrl,
      incidentReportCountChartUrl,
      incidentReportMetricsChartUrl,
      incidentReportChartMode,
      incidentReportChartData: chartDataSummary,
      incidentReportTable,
      incidentReportStatus,
      incidentReportNotice,
      incidentReportDeterministicReply,
      incidentReportOutageCount: incidentReportOutageCountFinal,
      incidentReportProductFilter: base.incidentReportProductFilter ?? null,
      incidentReportProductLabel: base.incidentReportProductLabel ?? null,
      incidentReportSegmentFilter: base.incidentReportSegmentFilter ?? null,
      incidentReportSegmentLabel: base.incidentReportSegmentLabel ?? null,
      dashboardWidget: base.dashboardWidget ?? null,
      dashboardWidgetLabel: base.dashboardWidgetLabel ?? null,
    },
  },
];

/**
 * Hourly: Freshservice Analytics export API → parse CSV → classify → SQL upsert.
 */
const EXPORT_ID = '1fe8fb0f-bc52-4377-813e-54087dd43429';

function parseCsvLine(line) {
  const out = [];
  let cur = '';
  let inQ = false;
  for (let i = 0; i < line.length; i++) {
    const c = line[i];
    if (c === '"') {
      inQ = !inQ;
      continue;
    }
    if (c === ',' && !inQ) {
      out.push(cur.trim());
      cur = '';
      continue;
    }
    cur += c;
  }
  out.push(cur.trim());
  return out;
}

function parseCsv(text) {
  const lines = String(text || '')
    .split(/\r?\n/)
    .map((l) => l.trim())
    .filter(Boolean);
  if (lines.length < 2) return [];
  const headers = parseCsvLine(lines[0]).map((h) => h.replace(/^"|"$/g, ''));
  const rows = [];
  for (let i = 1; i < lines.length; i++) {
    const cols = parseCsvLine(lines[i]);
    const o = {};
    headers.forEach((h, idx) => {
      o[h] = (cols[idx] || '').replace(/^"|"$/g, '');
    });
    rows.push(o);
  }
  return rows;
}

function normalizeRow(raw) {
  const mapped = typeof mapExportRow === 'function' ? mapExportRow(raw) : raw;
  const classified = classifyIncidentRow({ ...mapped, raw_row: JSON.stringify(raw) });
  return {
    ticket_id: mapped.ticket_id,
    ticket_display_id: mapped.ticket_display_id,
    subject: mapped.subject || null,
    status: mapped.status || null,
    priority: mapped.priority || null,
    source: mapped.source || null,
    created_date: mapped.created_date || null,
    workspace: mapped.workspace || null,
    ticket_type: mapped.ticket_type || null,
    product: classified.product || mapped.product || null,
    issue_category: classified.issue_category,
    cause_segment: classified.cause_segment,
    third_party: classified.third_party,
    status_page_flag: classified.status_page_flag,
    mom_presented_flag: classified.mom_presented_flag,
    export_synced_at: new Date().toISOString().slice(0, 19).replace('T', ' '),
    raw_row: JSON.stringify(raw),
  };
}

function sqlEscape(v) {
  if (v == null) return 'NULL';
  return "'" + String(v).replace(/\\/g, '\\\\').replace(/'/g, "''") + "'";
}

const input = $input.first();
let csvText = '';
const j = input.json || {};
if (typeof j === 'string') csvText = j;
else if (typeof j.body === 'string') csvText = j.body;
else if (typeof j.data === 'string') csvText = j.data;
else if (input.binary?.data?.data) {
  csvText = Buffer.from(input.binary.data.data, 'base64').toString('utf8');
} else if (j.export?.url) {
  return [{ json: { _needsCsvDownload: true, exportUrl: j.export.url } }];
} else csvText = JSON.stringify(j);

if (csvText.startsWith('{') && csvText.includes('"export"')) {
  try {
    const parsed = JSON.parse(csvText);
    if (parsed.export?.url) {
      return [{ json: { _needsCsvDownload: true, exportUrl: parsed.export.url } }];
    }
  } catch (e) {
    /* */
  }
}

const parsed = parseCsv(csvText);
const normalized = parsed.map(normalizeRow).filter((r) => r.ticket_id);

if (!normalized.length) {
  return [
    {
      json: {
        syncStatus: 'empty',
        message: 'No rows in analytics CSV. Check export id and Freshservice schedule.',
        exportId: EXPORT_ID,
        csvPreview: csvText.slice(0, 500),
      },
    },
  ];
}

const BATCH = 25;
const out = [];
for (let i = 0; i < normalized.length; i += BATCH) {
  const batch = normalized.slice(i, i + BATCH);
  const values = batch
    .map(
      (r) =>
        `(${sqlEscape(r.ticket_id)},${sqlEscape(r.ticket_display_id)},${sqlEscape(r.subject)},${sqlEscape(r.status)},${sqlEscape(r.priority)},${sqlEscape(r.source)},${sqlEscape(r.created_date)},${sqlEscape(r.workspace)},${sqlEscape(r.ticket_type)},${sqlEscape(r.product)},${sqlEscape(r.issue_category)},${sqlEscape(r.cause_segment)},${sqlEscape(r.third_party)},${sqlEscape(r.status_page_flag)},${sqlEscape(r.mom_presented_flag)},${sqlEscape(r.export_synced_at)},${sqlEscape(r.raw_row)})`,
    )
    .join(',\n');
  const query = `INSERT INTO MIM_Analytics_export (
  ticket_id, ticket_display_id, subject, status, priority, source,
  created_date, workspace, ticket_type, product, issue_category, cause_segment,
  third_party, status_page_flag, mom_presented_flag, export_synced_at, raw_row
) VALUES
${values}
ON DUPLICATE KEY UPDATE
  ticket_display_id=VALUES(ticket_display_id),
  subject=VALUES(subject),
  status=VALUES(status),
  priority=VALUES(priority),
  source=VALUES(source),
  created_date=VALUES(created_date),
  workspace=VALUES(workspace),
  ticket_type=VALUES(ticket_type),
  product=COALESCE(VALUES(product), product),
  issue_category=VALUES(issue_category),
  cause_segment=VALUES(cause_segment),
  third_party=VALUES(third_party),
  status_page_flag=VALUES(status_page_flag),
  mom_presented_flag=VALUES(mom_presented_flag),
  export_synced_at=VALUES(export_synced_at),
  raw_row=VALUES(raw_row);`;
  out.push({
    json: {
      query,
      syncStatus: 'upsert_batch',
      batchSize: batch.length,
      totalRows: normalized.length,
      exportId: EXPORT_ID,
    },
  });
}

return out;
